// Temporary Zen-corner variant. Original garden is preserved as zen-original.*.
import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.180.0/build/three.module.js";
const packed = "";
const bytes=Uint8Array.from(atob(packed),c=>c.charCodeAt(0));
const DATA=await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).json();
export const ZEN_CORNER_VARIANT="zen-monolith";
export const ZEN_CORNER_TARGET_BOUNDS={minX:-15,maxX:27,minZ:-20,maxZ:40,width:42,depth:60};
export function createExportedScene(options={}) {
 const group=new THREE.Group(),model=new THREE.Group();group.name='ZenCorner | '+ZEN_CORNER_VARIANT;model.name=ZEN_CORNER_VARIANT;group.add(model);
 if(options.position)group.position.copy(Array.isArray(options.position)?new THREE.Vector3(...options.position):options.position);
 if(options.rotationY!==undefined)group.rotation.y=options.rotationY;
 if(options.scale!==undefined)group.scale.setScalar(options.scale);
 const geos=new Map();
 for(const [key,value] of Object.entries(DATA.geometry)){const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(value.position,3));geo.setAttribute('normal',new THREE.Float32BufferAttribute(value.normal,3));geos.set(key,geo);}
 const materials=DATA.materials.map(m=>new THREE.MeshStandardMaterial({name:m.name,color:new THREE.Color(...m.color.slice(0,3)),roughness:m.roughness,metalness:m.metalness,emissive:new THREE.Color(...m.emission),emissiveIntensity:m.emissionStrength}));
 for(const object of DATA.objects){const mesh=new THREE.Mesh(geos.get(object.geometry),materials[object.material]);mesh.name=object.name;mesh.castShadow=true;mesh.receiveShadow=true;model.add(mesh);}
 const boxes=DATA.colliders.map(b=>new THREE.Box3(new THREE.Vector3(...b.slice(0,3)),new THREE.Vector3(...b.slice(3))));
 const worldBox=new THREE.Box3();let status='ready';
 function checkCollision(candidate,current,radius=.35){
  if(status==='disposed')return false;group.updateWorldMatrix(true,true);
  for(const local of boxes){worldBox.copy(local).applyMatrix4(group.matrixWorld);if(candidate.y-2>=worldBox.max.y||candidate.y<=worldBox.min.y)continue;
   if(candidate.x>=worldBox.min.x-radius&&candidate.x<=worldBox.max.x+radius&&candidate.z>=worldBox.min.z-radius&&candidate.z<=worldBox.max.z+radius)return true;}
  return false;
 }
 function dispose(){if(status==='disposed')return;status='disposed';for(const geo of geos.values())geo.dispose();for(const material of materials)material.dispose();group.removeFromParent();group.clear();}
 const ready=Promise.resolve(model);options.onLoad?.(model);
 return {group,ready,checkCollision,update(){},handleClick(){return false;},startWaterfall(){},stopWaterfall(){},dispose,get waterfallActive(){return false;},get status(){return status;}};
}
export function createZenCorner(options={}) {return createExportedScene({...options,position:options.position??[0,0.005,20]});}
export default createZenCorner;
